# GOOD: Daemon with TTL and graceful shutdown
import signal

class AgentDaemon:
    def __init__(self, ttl_seconds=86400):
        self.ttl = ttl_seconds
        self.start_time = time.time()
        self.running = True
        signal.signal(signal.SIGTERM, self.shutdown)

    def shutdown(self, signum, frame):
        self.running = False

    def run(self):
        while self.running:
            if time.time() - self.start_time > self.ttl:
                break
            process_tasks()

